static void bridge_connected(struct bt_conn *conn, uint8_t err)
{
  if (err != 0)
    {
      BRIDGE_LOG("connection failed, err 0x%02x\n", err);
      if (bridge_adv_start() != 0)
        {
          g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
        }

      return;
    }

  g_bridge.conn = bt_conn_ref(conn);
  g_bridge.state = AI_WATCH_BLE_BSP_CONNECTED;
  BRIDGE_LOG("connected\n");
}

static void bridge_disconnected(struct bt_conn *conn, uint8_t reason)
{
  BRIDGE_LOG("disconnected, reason 0x%02x\n", reason);

  /* Subscription state must be re-read after the next connect: CCC
   * persistence is the stack's business, the cached mode is ours.
   */

  g_status_ccc = 0;
  g_data_ccc = 0;
  g_status_ind_pending = false;
  g_data_ind_pending = false;

  sched_lock();
  if (g_bridge.conn != NULL)
    {
      bt_conn_unref(g_bridge.conn);
      g_bridge.conn = NULL;
    }

  /* When the radio is disabled through the app switch the state stays
   * OFF; otherwise it becomes DISCONNECTED and the application main
   * loop drives re-advertising through
   * ai_watch_ble_bsp_resume_advertising() (the RX context is not a
   * reliable place for the HCI command sequence, and BT_LE_ADV_CONN_*
   * includes the ONE_TIME flag, so the host does not auto-resume).
   */

  g_bridge.state = g_bridge.enabled ? AI_WATCH_BLE_BSP_DISCONNECTED
                                 : AI_WATCH_BLE_BSP_OFF;
  sched_unlock();
}

static struct bt_conn_cb g_bridge_conn_cbs =
{
  .connected = bridge_connected,
  .disconnected = bridge_disconnected,
  int ret;

  syslog(LOG_ERR, "aiwatch-ble: controller hardware error - recovering\n");

  /* 1. Restart the controller: power the LCPU off, re-init the mailbox,
   *    re-register the RX callback and boot a fresh LCPU (patches + RF
   *    calibration + ring sync).  After this the controller answers HCI
   *    again, so the host teardown below completes cleanly.  Any
   *    failure here stops the recovery: the host state is undefined
   *    past this point, and a later Hardware Error (or the Bluetooth
   *    toggle in Settings) retries the whole sequence. */

  {
    extern int sf32lb52_bth4_controller_restart(void);

    ret = sf32lb52_bth4_controller_restart();
    if (ret != 0)
      {
        syslog(LOG_ERR, "aiwatch-ble: controller restart failed: %d\n",
               ret);
        g_bridge.started = false;
        g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
        return;
      }
  }

  /* Drop our connection reference before the host cleanup fires the
   * disconnected callback (which owns the second unref). */

  if (g_bridge.conn != NULL)
    {
      bt_conn_unref(g_bridge.conn);
      g_bridge.conn = NULL;
    }
  g_bridge.started = false;
  g_bridge.state = AI_WATCH_BLE_BSP_OFF;

  /* 2. Tear the zblue host down.  bt_disable_mc force-completes even
   * when the controller ignores its HCI_RESET (HCI_RESET failure only
   * logs now), so this returns with the hdev freed and the driver
   * closed. */

  ret = bt_disable_mc(0);
  if (ret != 0)
    {
      syslog(LOG_ERR, "aiwatch-ble: host disable failed: %d\n", ret);
    }

  /* 3. Full bring-up: bt_enable -> bt_ready -> GATT service +
   * advertising.  The phone's retry loop reconnects on its own. */

  ret = ai_watch_ble_bsp_start();
  if (ret != 0)
    {
      g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
    }
}

bool ai_watch_ble_bsp_take_timesync(
    FAR struct ai_watch_ble_bsp_timesync_s *out)
{
  int ret;

  (void)drv;

  g_sf32lb52_bt_priv.rxlen = 0;
  g_sf32lb52_bt_priv.drop_rx_until_tx = true;

  ret = sf32lb52_bt_controller_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, "sf32lb52 bth4: controller_init failed: %d\n", ret);
      return ret;
    }

  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
  if (ret < 0)
    {
      syslog(LOG_ERR, "sf32lb52 bth4: register rx callback failed: %d\n",
             ret);
      return ret;
    }

  return OK;
}

static void sf32lb52_bt_close(struct bt_driver_s *drv)
{
  int ret;

  (void)drv;

  g_sf32lb52_bt_priv.rxlen = 0;

  /* Full deinit (not just disable) so that the next open re-initialises
   * the IPC queue from a clean state.  Without deinit, controller_init
   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
   * read pointer (reset on power-on) diverges from HCPU's stale write
   * pointer, causing all HCI commands to be silently dropped. */
  ret = sf32lb52_bt_controller_deinit();
  if (ret < 0)
    {
      wlerr("Failed to deinit HCI controller: %d\n", ret);
    }
}

int sf32lb52_bt_initialize(void)
{
  int ret;

  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb52_bt_priv.drv);
  if (ret < 0 && ret != -EEXIST)
    {
      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
      return ret;
    }

  sf32lb52_bt_zblue_init_once();

  return OK;
}

