/****************************************************************************
 * Name: ai_watch_ble_process
 ****************************************************************************/

void ai_watch_ble_process(void)
{
  struct ai_watch_ble_bsp_timesync_s sync;
  uint8_t cmd[AI_WATCH_BLE_CMD_MAX];
  size_t len;

  /* Deliver a pending validated TimeSync: RTC gets UTC, the timezone
   * offset is remembered for display only.
   */

  if (ai_watch_ble_bsp_take_timesync(&sync))
    {
      ai_ble_apply_timesync(&sync);
    }

  /* Drain all queued Command frames */

  while ((len = ai_watch_ble_bsp_take_command(cmd, sizeof(cmd))) > 0)
    {
      ai_ble_parse_command(cmd, len);
    }

  /* Raise banners for reminders whose trigger time just passed */

  ai_ble_check_due();

  /* Controller self-heal: if the LCPU bluetooth firmware reported a
   * hardware error, power-cycle it and rebuild the host stack. */

  if (ai_watch_ble_bsp_take_hw_error())
    {
      s_initfail_tries = 0;
      s_initfail_next.tv_sec = 0;
      ai_watch_ble_bsp_recover();
      return;
    }

  /* INIT_FAILED auto-recovery: a boot-time advertising failure (the LCPU
   * firmware wedging at an advertising-enable command, no Hardware
   * Error event) leaves the bridge dead until a power cycle - recover()
   * restarts the controller and re-runs the whole bring-up. The LCPU
   * failure is ~50% per bring-up (2026-10-24 logs), so five attempts
   * give ~97% of boots a working radio; the cap still bounds the UI
   * freeze a permanently broken controller would cause. Reaching a
   * link-active state or toggling the switch resets the cap. OFF is
   * deliberately NOT a reset: recover() passes through it during the
   * async re-bring-up. */

  {
    enum ai_watch_ble_bsp_state_e state = ai_watch_ble_get_state();

    if (state == AI_WATCH_BLE_BSP_ADVERTISING ||
        state == AI_WATCH_BLE_BSP_CONNECTED ||
        state == AI_WATCH_BLE_BSP_DISCONNECTED)
      {
        s_initfail_tries = 0;
        s_initfail_next.tv_sec = 0;
      }
    else if (state == AI_WATCH_BLE_BSP_INIT_FAILED &&
             s_initfail_tries < 5)
      {
        struct timespec now;

        clock_gettime(CLOCK_MONOTONIC, &now);

        if (s_initfail_next.tv_sec == 0)
          {
            /* first sighting: give the bring-up 10 s to settle before
             * the first attempt (monotonic 0 only before scheduling) */

            s_initfail_next = now;
            s_initfail_next.tv_sec += 10;
          }
        else if (now.tv_sec >= s_initfail_next.tv_sec)
          {
            s_initfail_tries++;
            s_initfail_next = now;
            s_initfail_next.tv_sec += 30;
            syslog(LOG_WARNING,
                   "aiwatch-ble: INIT_FAILED, auto-recover attempt %d\n",
                   s_initfail_tries);
            ai_watch_ble_bsp_recover();
            return;
          }
      }
  }

  /* Auto-reconnect: after a link loss, retry re-advertising once per
   * second from this (application) thread until it succeeds - the
   * bridge cannot run the HCI command sequence reliably from its RX
   * context, and the host does not auto-resume ONE_TIME advertising.
   */

  if (ai_watch_ble_get_state() == AI_WATCH_BLE_BSP_DISCONNECTED)
    {
      static struct timespec next_retry;
      struct timespec now;

      clock_gettime(CLOCK_MONOTONIC, &now);

      if (now.tv_sec >= next_retry.tv_sec)
        {
          ai_watch_ble_bsp_resume_advertising();
          next_retry = now;
          next_retry.tv_sec += 1;
        }
    }
}

