 *   Command    (f4) 12345678-9abc-def0-1234-56789abcdef4
 *
 * BT_UUID_128_ENCODE emits the little-endian byte order required on air.
 ****************************************************************************/

static void bridge_connected(struct bt_conn *conn, uint8_t err)
{
  if (err != 0)
    {
      BRIDGE_LOG("connection failed, err 0x%02x\n", err);
      if (bridge_adv_start() != 0)
        {
          g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
        }

      return;
    }

  g_bridge.conn = bt_conn_ref(conn);
  g_bridge.state = AI_WATCH_BLE_BSP_CONNECTED;
  BRIDGE_LOG("connected\n");
}

static void bridge_disconnected(struct bt_conn *conn, uint8_t reason)
{
  BRIDGE_LOG("disconnected, reason 0x%02x\n", reason);

  /* Subscription state must be re-read after the next connect: CCC
   * persistence is the stack's business, the cached mode is ours.
   */

  g_status_ccc = 0;
  g_data_ccc = 0;
  g_status_ind_pending = false;
  g_data_ind_pending = false;

  sched_lock();
  if (g_bridge.conn != NULL)
    {
      bt_conn_unref(g_bridge.conn);
      g_bridge.conn = NULL;
    }

  /* When the radio is disabled through the app switch the state stays
   * OFF; otherwise it becomes DISCONNECTED and the application main
   * loop drives re-advertising through
   * ai_watch_ble_bsp_resume_advertising() (the RX context is not a
   * reliable place for the HCI command sequence, and BT_LE_ADV_CONN_*
   * includes the ONE_TIME flag, so the host does not auto-resume).
   */

  g_bridge.state = g_bridge.enabled ? AI_WATCH_BLE_BSP_DISCONNECTED
                                 : AI_WATCH_BLE_BSP_OFF;
  sched_unlock();
}

static struct bt_conn_cb g_bridge_conn_cbs =
{
  .connected = bridge_connected,
  .disconnected = bridge_disconnected,
};

static void bridge_conn_cb_register(void)
{
  /* Every bt_enable builds a fresh host whose callback list starts
   * empty (bt_disable_mc -> bt_dev_free wipes conn_ctx), so this must
   * run once per host generation, NOT once per process. */
  bt_conn_cb_register(&g_bridge_conn_cbs);
}


/****************************************************************************
 * Public Functions - wrapper implementation (see ai_watch_ble_bsp.h)
 ****************************************************************************/

static void bridge_hw_error_notify(uint8_t dev_id);

int ai_watch_ble_bsp_start(void)
{
  int err;

  if (g_bridge.started)
    {
      return 0;
    }

  g_bridge.started = true;
  g_bridge.enabled = true;
  bt_hci_hw_error_cb_register(bridge_hw_error_notify);

  /* Do NOT register conn callbacks here: in this zblue port
   * bt_conn_cb_register_mc() dereferences hdev->conn_ctx, which only
   * exists after bt_enable() has initialized the host. Registration
   * happens in bridge_bt_ready() instead.
   */

  /* bt_enable opens /dev/ttyHCI0 (CONFIG_BT_UART_ON_DEV_NAME), which
   * powers up the LCPU BLE controller on first open.
   */

  err = bt_enable(bridge_bt_ready);
  if (err != 0)
    {
      BRIDGE_LOG("bt_enable rejected: %d\n", err);
      g_bridge.started = false;   /* allow a later retry */
      g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
      return err;
    }

  /* Completion is asynchronous: state flips in bridge_bt_ready() */

  return 0;
}

enum ai_watch_ble_bsp_state_e ai_watch_ble_bsp_get_state(void)
{
  return g_bridge.state;
}

/* Called by the zblue RX thread when the controller reports a
 * Hardware Error event (the LCPU bluetooth firmware died).  Only sets
 * a flag; the recovery itself runs on the application main loop.
 * Registered in ai_watch_ble_bsp_start().
 */
static void bridge_hw_error_notify(uint8_t dev_id)
{
  (void)dev_id;
  g_bridge.hw_error_pending = true;
}

bool ai_watch_ble_bsp_take_hw_error(void)
{
  struct timespec now;

  if (!g_bridge.hw_error_pending)
    {
      return false;
    }

  clock_gettime(CLOCK_MONOTONIC, &now);
  /* Rate limit: last_recover_sec == 0 means "never recovered"
   * (CLOCK_MONOTONIC starts at 0 - a plain `now < last + 10` would
   * swallow the first recovery during the first 10s of uptime).  While
   * gated, the pending flag is PRESERVED so the event is not lost. */
  if (g_bridge.last_recover_sec != 0 &&
      now.tv_sec < g_bridge.last_recover_sec + 10)
    {
      return false;
    }

  g_bridge.hw_error_pending = false;
  g_bridge.last_recover_sec = now.tv_sec;
  return true;
}

void ai_watch_ble_bsp_recover(void)
{
  int ret;

  syslog(LOG_ERR, "aiwatch-ble: controller hardware error - recovering\n");

  /* 1. Restart the controller: power the LCPU off, re-init the mailbox,
   *    re-register the RX callback and boot a fresh LCPU (patches + RF
   *    calibration + ring sync).  After this the controller answers HCI
   *    again, so the host teardown below completes cleanly.  Any
   *    failure here stops the recovery: the host state is undefined
   *    past this point, and a later Hardware Error (or the Bluetooth
   *    toggle in Settings) retries the whole sequence. */

  {
    extern int sf32lb52_bth4_controller_restart(void);

    ret = sf32lb52_bth4_controller_restart();
    if (ret != 0)
      {
        syslog(LOG_ERR, "aiwatch-ble: controller restart failed: %d\n",
               ret);
        g_bridge.started = false;
        g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
        return;
      }
  }

  /* Drop our connection reference before the host cleanup fires the
   * disconnected callback (which owns the second unref). */

  if (g_bridge.conn != NULL)
    {
      bt_conn_unref(g_bridge.conn);
      g_bridge.conn = NULL;
    }
  g_bridge.started = false;
  g_bridge.state = AI_WATCH_BLE_BSP_OFF;

