int bt_enable_mc(uint8_t dev_id, bt_ready_cb_t cb)
{
	int err;
	struct bt_dev *hdev;

	hdev = bt_dev_alloc(dev_id);
	if (!hdev) {
		return -ENODEV;
	}

#if DT_HAS_CHOSEN(zephyr_bt_hci)
	if (!device_is_ready(hdev->hci)) {
		LOG_ERR("HCI driver is not ready");
		return -ENODEV;
	}

	bt_monitor_new_index(BT_MONITOR_TYPE_PRIMARY, BT_HCI_BUS, BT_ADDR_ANY, BT_HCI_NAME);
#else /* !DT_HAS_CHONSEN(zephyr_bt_hci) */
	if (!hdev->drv) {
		LOG_ERR("No HCI driver registered");
		return -ENODEV;
	}
#endif

	atomic_clear_bit(hdev->flags, BT_DEV_DISABLE);

	if (atomic_test_and_set_bit(hdev->flags, BT_DEV_ENABLE)) {
		if (cb) {
			cb(hdev->dev_id, 0);
		}
		return 0;
	}

#if defined(CONFIG_BT_SMP) || defined(CONFIG_BT_CLASSIC)
	bt_keys_reset(hdev);
#endif

	if (IS_ENABLED(CONFIG_BT_SETTINGS)) {
		err = bt_settings_init(hdev);
		if (err) {
			return err;
		}
	} else if (IS_ENABLED(CONFIG_BT_DEVICE_NAME_DYNAMIC)) {
		err = bt_set_name_mc(dev_id, CONFIG_BT_DEVICE_NAME);
		if (err) {
			LOG_WRN("Failed to set device name (%d)", err);
		}
	}

	hdev->ready_cb = cb;

	/* Give cmd_sem allowing to send first HCI_Reset cmd, the only
	 * exception is if the controller requests to wait for an
	 * initial Command Complete for NOP.
	 */
	if (!IS_ENABLED(CONFIG_BT_WAIT_NOP)) {
		k_sem_init(&hdev->ncmd_sem, 1, 1);
	} else {
		k_sem_init(&hdev->ncmd_sem, 0, 1);
	}
	k_fifo_init(&hdev->cmd_tx_queue);

#if defined(CONFIG_BT_RECV_WORKQ_BT)
	/* RX thread */
	if (bt_workq.flags & K_WORK_QUEUE_STARTED) {
		LOG_DBG("Work queue already started");
	} else {
		k_work_queue_init(&bt_workq);
		k_work_queue_start(&bt_workq, rx_thread_stack,
				CONFIG_BT_RX_STACK_SIZE,
				K_PRIO_COOP(CONFIG_BT_RX_PRIO), NULL);
		k_thread_name_set(&bt_workq.thread, "BT RX WQ");
	}	
#endif

	k_work_init(&hdev->rx_work, rx_work_handler);

