int bt_disable_mc(uint8_t dev_id)
{
	int err;
	struct bt_dev *hdev;

	hdev = bt_dev_get(dev_id);
	if (!hdev) {
		return -ENODEV;
	}

#if !DT_HAS_CHOSEN(zephyr_bt_hci)
	if (!hdev->drv) {
		LOG_ERR("No HCI driver registered");
		bt_dev_free(hdev);
		return -ENODEV;
	}

	if (!hdev->drv->close) {
		bt_dev_free(hdev);
		return -ENOTSUP;
	}
#endif

	if (atomic_test_and_set_bit(hdev->flags, BT_DEV_DISABLE)) {
		/* A disable is already in progress: its owner performs the
		 * teardown (driver close + hdev free).  Freeing here would
		 * skip the driver close entirely. */
		return -EALREADY;
	}

	/* Clear BT_DEV_READY before disabling HCI link */
	atomic_clear_bit(hdev->flags, BT_DEV_READY);

#if defined(CONFIG_BT_BROADCASTER)
	bt_adv_reset_adv_pool(hdev);
#endif /* CONFIG_BT_BROADCASTER */

#if defined(CONFIG_BT_PRIVACY)
	k_work_cancel_delayable(&hdev->rpa_update);
#endif /* CONFIG_BT_PRIVACY */

#if defined(CONFIG_BT_PER_ADV_SYNC)
	bt_periodic_sync_disable(hdev);
#endif /* CONFIG_BT_PER_ADV_SYNC */

#if defined(CONFIG_BT_CONN)
	if (IS_ENABLED(CONFIG_BT_SMP)) {
		bt_pub_key_hci_disrupted(hdev);
	}
	bt_conn_cleanup_all(hdev);
	disconnected_handles_reset(hdev);
#endif /* CONFIG_BT_CONN */

	/* Reset the Controller */
	if (!drv_quirk_no_reset(hdev)) {

		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_RESET, NULL, NULL);
		if (err) {
			/* Controller unresponsive (e.g. it reported a
			 * Hardware Error): force the teardown anyway.  The
			 * platform power-cycles the controller right after
			 * this, so skipping the HCI_Reset bookkeeping is
			 * safe.  Returning here would leave BT_DEV_DISABLE
			 * set and the hdev allocated, permanently breaking
			 * later bt_enable_mc() calls. */
			LOG_WRN("HCI_Reset failed (%d) - forcing teardown",
				err);
		} else {
			hci_reset_complete(hdev);
		}
	}

#if DT_HAS_CHOSEN(zephyr_bt_hci)
	err = bt_hci_close(hdev->hci);
	if (err == -ENOSYS) {
		atomic_clear_bit(hdev->flags, BT_DEV_DISABLE);
		atomic_set_bit(hdev->flags, BT_DEV_READY);
		bt_dev_free(hdev);
		return -ENOTSUP;
	}
#else
	err = hdev->drv->close();
#endif
	if (err) {
		LOG_ERR("HCI driver close failed (%d)", err);

		/* Re-enable BT_DEV_READY to avoid inconsistent stack state */
		atomic_set_bit(hdev->flags, BT_DEV_READY);
		bt_dev_free(hdev);

		return err;
	}

#if defined(CONFIG_BT_RECV_WORKQ_BT)
	/* Abort RX thread */
	k_thread_abort(&bt_workq.thread);
	bt_workq.flags &= ~K_WORK_QUEUE_STARTED;
#endif

	/* Some functions rely on checking this bitfield */
	memset(hdev->supported_commands, 0x00, sizeof(hdev->supported_commands));

	/* Reset IDs and corresponding keys. */
	hdev->id_count = 0;
#if defined(CONFIG_BT_SMP)
	hdev->le.rl_entries = 0;
#endif

#if defined(CONFIG_BT_SMP) || defined(CONFIG_BT_CLASSIC)
	bt_keys_reset(hdev);
#endif
	/* If random address was set up - clear it */
	bt_addr_le_copy(&hdev->random_addr, BT_ADDR_LE_ANY);

	if (IS_ENABLED(CONFIG_BT_ISO)) {
		bt_iso_reset(hdev);
	}

	bt_monitor_send(BT_MONITOR_CLOSE_INDEX, NULL, 0);

	/* Clear BT_DEV_ENABLE here to prevent early bt_enable() calls, before disable is
	 * completed.
	 */
	atomic_clear_bit(hdev->flags, BT_DEV_ENABLE);

	bt_dev_free(hdev);

	return 0;
}

