834	  /* The LCPU initializes its TX ring during boot and may publish boot
835	   * responses before this wait completes.  The pre-release hook invalidates
836	   * the retained header so readiness cannot be inferred from an old ring.
837	   * HCPU now synchronizes its read pointer to the fresh producer pointer:
838	   *
839	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
840	   *
841	   * returns a large garbage value, and LCPU's fresh boot events
842	   * plus ring garbage all replay as "new" HCI responses.  These
843	   * ghost events are consumed by the host as replies to real commands,
844	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
845	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
846	   *
847	   * Fix: flush DCache to write back any dirty read_idx and to load
848	   * LCPU's current write_idx from SRAM, then advance read_idx to
849	   * write_idx (discard ALL pending LCPU boot data), then clean the
850	   * DCache so LCPU sees the updated read pointer in SRAM.
851	   */
852	
853	  {
854	    struct circular_buf *rx_ring =
855	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
856	
857	    ret = sf32lb52_bt_wait_rx_ring_ready();
858	    if (ret < 0)
859	      {
860	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
861	        g_sf32lb52_bt_env.queue_open = false;
862	        g_sf32lb52_bt_env.rx_enabled = false;
863	        g_sf32lb52_bt_env.rx_work_pending = false;
864	        g_sf32lb52_bt_env.rx_worker_running = false;
865	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
866	        if (!work_available(&g_sf32lb52_bt_env.rx_work))
867	          {
868	            work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
869	          }
870	
871	        lcpu_power_off();
872	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
873	        g_sf32lb52_bt_env.wake_held = false;
874	        return ret;
875	      }
876	
877	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
878	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
879	
880	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
881	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
882	                    sizeof(*rx_ring));
883	    __DSB();
884	
885	    irqstate_t flags = enter_critical_section();
886	    L2H_MAILBOX->CxICR = MAILBOX2_C1ICR_INT0_Msk;
887	    L2H_MAILBOX->CxIER |= MAILBOX2_C1IER_INT0_Msk;
