694	bool ai_watch_ble_bsp_take_controller_fault(void)
695	{
696	  struct timespec now;
697	  bool pending;
698	
699	  sched_lock();
700	  pending = g_bridge.controller_fault_pending;
701	  if (!pending || g_bridge.recovering)
702	    {
703	      sched_unlock();
704	      return false;
705	    }
706	
707	  clock_gettime(CLOCK_MONOTONIC, &now);
708	  /* Rate limit: last_recover_sec == 0 means "never recovered"
709	   * (CLOCK_MONOTONIC starts at 0 - a plain `now < last + 10` would
710	   * swallow the first recovery during the first 10s of uptime).  While
711	   * gated, the pending flag is PRESERVED so the fault is not lost. */
712	  if (g_bridge.last_recover_sec != 0 &&
713	      now.tv_sec < g_bridge.last_recover_sec + 10)
714	    {
715	      sched_unlock();
716	      return false;
717	    }
718	
719	  g_bridge.controller_fault_pending = false;
720	  g_bridge.recovering = true;
721	  g_bridge.last_recover_sec = now.tv_sec;
722	  sched_unlock();
723	  return true;
724	}
