726	void ai_watch_ble_bsp_recover(void)
727	{
728	  int ret;
729	  bool restart_enabled;
730	  uint8_t fault_type;
731	  uint16_t fault_opcode;
732	  extern void sf32lb52_lcpu_boot_dump_evidence(void);
733	
734	  sched_lock();
735	  restart_enabled = g_bridge.enabled;
736	  fault_type = g_bridge.controller_fault_type;
737	  fault_opcode = g_bridge.controller_fault_opcode;
738	  g_bridge.recovering = true;
739	  g_bridge.controller_fault_pending = false;
740	  g_bridge.controller_fault_type = BRIDGE_CONTROLLER_FAULT_NONE;
741	  sched_unlock();
742	
743	  syslog(LOG_ERR,
744	         "aiwatch-ble: controller recovery type=%s opcode=0x%04x\n",
745	         fault_type == BRIDGE_CONTROLLER_FAULT_CMD_TIMEOUT ?
746	           "command-timeout" :
747	         fault_type == BRIDGE_CONTROLLER_FAULT_HW_ERROR ?
748	           "hardware-error" : "init-failed",
749	         fault_opcode);
750	  sf32lb52_lcpu_boot_dump_evidence();
751	
752	  /* Stop the host and close the H4 driver before rebuilding the
753	   * controller. Driver close deinitializes IPC and halts the LCPU; the
754	   * next host open creates a fresh queue before issuing HCI commands. */
755	
756	  if (g_bridge.conn != NULL)
757	    {
758	      bt_conn_unref(g_bridge.conn);
759	      g_bridge.conn = NULL;
760	    }
761	  g_bridge.started = false;
762	  g_bridge.state = AI_WATCH_BLE_BSP_OFF;
763	
764	  /* The controller has reported a fatal error or stopped answering
765	   * commands. Skip HCI_Reset and close the driver to halt the LCPU. */
766	
767	  syslog(LOG_ERR, "aiwatch-ble: force host teardown begin\n");
768	  ret = bt_disable_force_mc(0);
769	  syslog(LOG_ERR, "aiwatch-ble: force host teardown result=%d\n", ret);
770	  if (ret != 0 && ret != -ENODEV)
771	    {
772	      syslog(LOG_ERR, "aiwatch-ble: host disable failed: %d\n", ret);
773	      sched_lock();
774	      g_bridge.recovering = false;
775	      g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
776	      sched_unlock();
777	      return;
778	    }
779	
780	  sched_lock();
781	  g_bridge.recovering = false;
782	  if (!restart_enabled)
783	    {
784	      g_bridge.state = AI_WATCH_BLE_BSP_OFF;
785	      sched_unlock();
786	      return;
787	    }
788	  sched_unlock();
789	
790	  /* Full bring-up: bt_enable -> bt_ready -> GATT service + advertising. */
791	  ret = ai_watch_ble_bsp_start();
792	  if (ret != 0)
793	    {
794	      g_bridge.state = AI_WATCH_BLE_BSP_INIT_FAILED;
795	    }
796	}
